def f(a: int, b: int) -> int:
    """Returns twice the smaller absolute input, with the sign of a*b; returns 0 if either input is 0."""
    if a == 0 or b == 0:
        return 0
    m = abs(a) if abs(a) < abs(b) else abs(b)
    return 2 * m if a * b > 0 else -2 * m

